changeSet.sql:

if not exists (SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_NAME ='UC_AssetTag_AssetID_TagID')
begin
	alter table AssetTag add constraint UC_AssetTag_AssetID_TagID unique (AssetID, TagID);
end

changeSet.rollback:

if exists (SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_NAME ='UC_AssetTag_AssetID_TagID')
begin
	alter table AssetTag drop constraint UC_AssetTag_AssetID_TagID;
end
